<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import AppIcon from './AppIcon.vue'
import {useStudio} from './studioContext'
import {selectFiltered} from './smartEditRuntime'
const props=defineProps<{data:any;policy:any;prepare:()=>Promise<void>}>(),s=useStudio()
const emit=defineEmits<{locate:[ids:string[]];smart:[ids:string[]]}>()
const query=ref(''),filter=ref('all'),lane=ref('main'),selected=ref<string[]>([]),groups=ref<string[]>([]),page=ref(1)
const people=computed(()=>props.data.people||[])
const lanes=computed(()=>({main:people.value.filter((r:any)=>props.policy.mainIds.includes(r.id)),candidate:people.value.filter((r:any)=>props.policy.candidateIds.includes(r.id)),other:people.value.filter((r:any)=>props.policy.otherIds.includes(r.id))}))
const matches=(rows:any[])=>rows.filter(r=>(!query.value||(r.name+' '+(r.aliases||[]).map((a:any)=>a.name||a).join(' ')+' '+(r.summary||'')).includes(query.value))&&(lane.value!=='other'||filter.value==='all'||r.scope===filter.value))
const current=computed(()=>matches((lanes.value as any)[lane.value]||[]))
const otherRows=computed(()=>matches(lanes.value.other)),duplicates=computed(()=>props.policy.duplicateGroups||[])
const countLabel=computed(()=>`${lanes.value.main.length} 位画中角色 · ${lanes.value.candidate.length} 位补充候选 · ${lanes.value.other.length} 位其他资料人物`)
function toggle(id:string,checked:boolean){selected.value=selectFiltered(selected.value,[id],checked)}
function profile(r:any){const text=r.summary||props.data.statements.filter((v:any)=>v.personId===r.id).map((v:any)=>v.text).join('；');const brief=(text||'').split(/(?<=[。！？；])/u).filter(Boolean).slice(0,2).join('');return brief.length>110?brief.slice(0,110)+'…':brief||'资料未提供具体经历。'}
function activate(name:string,e:Event){if((e.target as HTMLDetailsElement).open){lane.value=name;page.value=1}else if(lane.value===name)lane.value='main'}
async function bulk(action:string){if(!selected.value.length)return;await s.runSmartAction({kind:'library',section:'people',itemIds:selected.value},{peopleAction:action},props.prepare)}
async function merge(){const chosen=duplicates.value.filter((g:any)=>groups.value.includes(g.id));if(!chosen.length)return;await s.runSmartAction({kind:'library',section:'people',itemIds:[...new Set(chosen.flatMap((g:any)=>g.personIds))]},{peopleAction:'merge_groups',groups:chosen.map((g:any)=>({personIds:g.personIds,survivorId:g.survivorId}))},props.prepare)}
watch([query,filter],()=>page.value=1)
watch(()=>props.data.people.map((r:any)=>r.id).join(','),()=>{const ids=new Set(people.value.map((r:any)=>r.id));selected.value=selected.value.filter(id=>ids.has(id));groups.value=groups.value.filter(id=>duplicates.value.some((g:any)=>g.id===id))})
</script>
<template><div class="people-browser"><p class="people-count">{{countLabel}}</p>
 <div class="people-tools"><input v-model="query" aria-label="搜索资料人物" placeholder="搜索姓名、称谓或简介"><small>已选 {{selected.length}} 位</small><button @click="selected=selectFiltered(selected,current.map((r:any)=>r.id),true)">全选当前筛选结果（{{current.length}}）</button><button :disabled="!selected.length" @click="selected=[]">取消选择</button></div>
 <div v-if="selected.length" class="people-bulk"><button :disabled="s.generating.value" @click="bulk('include')">加入画中人物</button><button :disabled="s.generating.value" @click="bulk('exclude')">仅保留为资料人物</button><button @click="emit('smart',selected)"><AppIcon name="ai" :size="13"/>智能修改所选</button><small>批量归类不调用模型，可撤销。</small></div>
 <article v-for="person in matches(lanes.main)" :key="person.id" class="cast-person"><div class="cast-title"><label><input type="checkbox" :checked="selected.includes(person.id)" :aria-label="'选择人物：'+person.name" @change="lane='main';toggle(person.id,($event.target as HTMLInputElement).checked)"><b>{{person.name}}</b></label><small>{{person.roleType==='group'?'群体角色':'画中角色'}}{{person.annotationIds?.length?' · '+person.annotationIds.length+' 个实例':''}}</small></div><p>{{profile(person)}}</p><small v-if="person.aliases?.length">其他称谓：{{person.aliases.map((a:any)=>a.name||a).join('、')}}</small><div class="cast-actions"><button @click="emit('smart',[person.id])"><AppIcon name="ai" :size="13"/>智能修改</button><button :disabled="!person.referenceIds?.length" @click="emit('locate',person.referenceIds)">对应原文</button><button v-if="person.characterId" @click="s.navigate('characters','character:'+person.characterId)">人物档案</button></div><details><summary>展开人物依据</summary><div v-for="line in data.statements.filter((r:any)=>r.personId===person.id)" :key="line.id"><small>{{line.aspect}}</small><p>{{line.text}}</p><button :disabled="!line.referenceIds?.length" @click="emit('locate',line.referenceIds)">查看依据</button></div></details></article>
 <p v-if="!lanes.main.length" class="people-empty">尚无画中角色。可从补充候选中选择加入，或在画作中手动命名。</p>
 <details v-if="lanes.candidate.length" class="people-secondary" @toggle="activate('candidate',$event)"><summary>补充候选（{{lanes.candidate.length}}） · 尚未加入创作角色</summary><p class="people-explanation">已有画中提及，但可能是现有人物的另一称谓。按需查看，不要求逐项确认。</p><article v-for="r in matches(lanes.candidate)" :key="r.id" class="mention-row"><label><input type="checkbox" :checked="selected.includes(r.id)" @change="toggle(r.id,($event.target as HTMLInputElement).checked)"><b>{{r.name}}</b></label><p>{{profile(r)}}</p><button @click="emit('locate',r.referenceIds)">原文</button><button @click="emit('smart',[r.id])"><AppIcon name="ai" :size="13"/>智能修改</button></article></details>
 <details v-if="duplicates.length" class="people-secondary" @toggle="page=1"><summary>称谓归并建议（{{duplicates.length}} 组） · 可选处理</summary><p class="people-explanation">每一组独立归并，不会把所有勾选人物合成一个人。不同身影与群体实例保持不变。</p><label v-for="group in duplicates" :key="group.id" class="merge-group"><input type="checkbox" :value="group.id" v-model="groups"><span><b>{{group.names.join(' ／ ')}}</b><small>{{group.reason}}</small></span></label><button :disabled="!groups.length||s.generating.value" @click="merge">采用选中的 {{groups.length}} 组归并建议</button></details>
 <details v-if="lanes.other.length" class="people-secondary" @toggle="activate('other',$event)"><summary>其他资料人物（{{lanes.other.length}}） · 背景、研究者与范围未定</summary><p class="people-explanation">不进入画中候选或自动角色生成；原文及其对理解故事的作用保留。</p><select v-model="filter" aria-label="其他资料人物筛选"><option value="all">全部其他资料人物</option><option value="background">仅背景人物</option><option value="unknown">范围未定</option></select><div class="mention-pagination"><span>{{otherRows.length}} 条结果 · 第 {{page}} 页</span><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page*20>=otherRows.length" @click="page++">下一页</button></div><article v-for="r in otherRows.slice((page-1)*20,page*20)" :key="r.id" class="mention-row"><label><input type="checkbox" :checked="selected.includes(r.id)" @change="toggle(r.id,($event.target as HTMLInputElement).checked)"><b>{{r.name}}</b></label><p>{{profile(r)}}</p><small>{{r.inclusionDecision==='exclude'?'已选择仅保留资料':r.scope==='background'?'背景人物':'范围未定'}}</small><button :disabled="!r.referenceIds?.length" @click="emit('locate',r.referenceIds)">原文</button></article></details>
</div></template>
<style scoped>.people-count{font-size:12px;color:#728367;line-height:1.8}.people-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 0}.people-tools input{flex:1;min-width:160px;font-size:12px}.people-tools small{font-size:11px;color:#718569;white-space:nowrap}.people-tools button,.people-browser button{font-size:11px;padding:5px 8px}.people-bulk{display:flex;gap:7px;align-items:center;flex-wrap:wrap;background:#edf4e7;padding:10px;border-radius:7px}.people-bulk small{font-size:10px;color:#87917c}.cast-person{border-top:1px solid #e5ecdd;padding:14px 0}.cast-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.cast-title label,.mention-row label{display:flex;align-items:center;gap:7px;font-size:12px;margin:0}.people-browser input[type=checkbox]{width:auto}.cast-title small,.cast-person>small{font-size:10px;color:#87937b}.cast-person p{font-size:12px;line-height:1.9;color:#64755a;margin:9px 0}.cast-actions{display:flex;gap:6px;margin:9px 0}.cast-actions button,.people-bulk button:last-of-type{display:inline-flex;align-items:center;gap:5px}.people-browser summary{font-size:11px;color:#7b8b6e;cursor:pointer}.people-secondary{margin-top:16px;padding-top:14px;border-top:1px solid #e5ecdd}.people-explanation,.people-empty{font-size:12px;color:#8b967f;line-height:1.8}.mention-row{display:grid;grid-template-columns:140px minmax(0,1fr) auto;gap:8px 12px;align-items:start;border-top:1px solid #edf0e5;padding:11px 0}.mention-row p{font-size:11px;line-height:1.8;margin:0;color:#7a856e}.mention-row small{font-size:10px;color:#8e987e}.mention-pagination{display:flex;align-items:center;gap:10px;margin:12px 0;font-size:11px;color:#819075}.merge-group{display:flex;align-items:start;gap:9px;font-size:12px;padding:10px 0}.merge-group small{display:block;font-size:11px;font-weight:400;color:#8a967d;margin-top:5px}</style>
